package com.playsphere.payment;
import com.playsphere.common.Ids;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="payments") public class Payment{
 @Id @Column(length=36) private String id;@Column(name="user_id",nullable=false,length=36) private String userId;@Column(nullable=false,length=32) private String purpose;@Column(name="reference_id",nullable=false,length=36) private String referenceId;@Column(nullable=false,length=32) private String provider;@Column(name="provider_order_id",length=120) private String providerOrderId;@Column(name="provider_payment_id",length=120) private String providerPaymentId;@Column(nullable=false,precision=12,scale=2) private BigDecimal amount;@Column(nullable=false,length=8) private String currency;@Column(nullable=false,length=24) private String status;@Column(name="created_at",nullable=false) private Instant createdAt;@Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected Payment(){}public Payment(String user,String purpose,String ref,String provider,BigDecimal amount){id=Ids.uuid();userId=user;this.purpose=purpose;referenceId=ref;this.provider=provider;this.amount=amount;currency="INR";status="CREATED";createdAt=updatedAt=Instant.now();}
 public String getId(){return id;}public String getUserId(){return userId;}public String getPurpose(){return purpose;}public String getReferenceId(){return referenceId;}public String getProvider(){return provider;}public String getProviderOrderId(){return providerOrderId;}public String getProviderPaymentId(){return providerPaymentId;}public BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void order(String provider,String order){this.provider=provider;providerOrderId=order;status="PENDING";updatedAt=Instant.now();}public void success(String payment){providerPaymentId=payment;status="SUCCESS";updatedAt=Instant.now();}public void refunded(){status="REFUNDED";updatedAt=Instant.now();}
}
